import{_ as t,o as a,c as s,ao as n}from"./chunks/framework.DOMnz-Zz.js";const u=JSON.parse('{"title":"Updating and rollback","description":"","frontmatter":{},"headers":[],"relativePath":"guide/updating.md","filePath":"guide/updating.md","lastUpdated":null}'),o={name:"guide/updating.md"};function i(d,e,r,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="updating" tabindex="-1">Updating and rollback <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating and rollback {#updating}&quot;">​</a></h1><p>Updating a release install on Linux, macOS or Windows is one command. Tell a coding agent running on the machine</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update sot from the repo</span></span></code></pre></div><p>or run it yourself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/sot/repo/current/scripts/install.sh</span></span></code></pre></div><p>On Windows the same entry is <code>install.ps1</code> in the installed checkout (its versions path also works over ssh, where <code>repo\\current</code> cannot be traversed):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOCALAPPDATA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\sot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; $t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\install.json&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ConvertFrom-Json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).tag</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoProfile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\repo\\versions\\</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\scripts\\install.ps1&quot;</span></span></code></pre></div><p>Its options are <code>-Version</code>, <code>-Archive</code>, <code>-Hub</code>, <code>-Prefix</code> and <code>-RestartDaemon</code>, and it ends in the same one line. A <code>ONE STEP LEFT</code> there is usually to quit Ship of Tools (choose Keep) and start it from the shortcut, when the window&#39;s launcher is older than release candidate 9.13 or no window is up to be told, or to start it at the desk when the run was over ssh; with a current launcher running, the entry asks it to converge and waits for it, and your sessions keep running.</p><p>With no options it moves to the newest release on the channel the machine already runs (a stable release follows the stable releases; a release candidate follows the candidates), and never moves the install backwards. The role is decided in this order: <code>hosts.toml</code>&#39;s entry for this computer first (it wins over a role flag); then the role flag, used only when the topology names no entry; then the role the install recorded, used only when there is no flag either. An update therefore needs no role flag. On Windows there is no role flag, and every box runs its local daemon (<code>install.json</code> records <code>daemon</code> and <code>frontend</code> as true). Where no Julia is found the update&#39;s stage skips the Julia environments instead of failing: the launcher prepares them at the new version&#39;s first start, and the run ends with a step naming <code>winget install --id Julialang.Juliaup -e</code>. A run can take many minutes (the stage prepares Julia, and a converge waits up to 30 minutes for the window), so a coding agent runs it in the background or with the longest timeout and reads the last line of its output. It ends with exactly one line:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Last line</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>PASS: Ship of Tools &lt;v&gt; at &lt;commit&gt; on this computer</code></td><td style="text-align:right;">Done: the binaries, the checkout, the Julia environments and the agent comm are on <code>&lt;v&gt;</code>.</td></tr><tr><td style="text-align:right;"><code>ONE STEP LEFT: &lt;step&gt;</code></td><td style="text-align:right;">The install is whole and one thing remains that only you can do, usually to quit the window and start it again, since it still runs the old version.</td></tr><tr><td style="text-align:right;"><code>FAIL: &lt;check&gt;: &lt;detail&gt;</code></td><td style="text-align:right;">Something did not hold. Run it again after fixing what the line names; a half-finished run is safe to repeat. A <code>FAIL</code> after the run wrote the pin ends with the pin text. On Windows, one after the run staged an update that is still armed also says <code>; the update to &lt;tag&gt; stays armed: the next start applies it</code> (<code>install.sh</code> arms no update itself).</td></tr></tbody></table><p>Three <code>FAIL</code> lines are questions rather than faults:</p><ul><li><p><code>daemon:</code> names the rows whose REPL is live and says when the Pluto server is running (restarting the daemon ends every notebook open in it, however it was opened), or says why the daemon could not be asked in full, naming the REPL rows it could read (a v0.6.5 daemon refuses the question, and a daemon older than the Pluto field cannot say whether its Pluto server is running, so the first update from either pays one flag). Updating restarts the backend, which ends those REPLs&#39; and notebooks&#39; variables (the rows and their agents keep running). Nothing under the install was changed. Run it again with <code>--restart-daemon</code> (Windows: <code>-RestartDaemon</code>) when that is fine. A daemon that is running but cannot be told its version (it does not answer, or refuses the question) is treated the same way: the run stops with <code>sotd</code>&#39;s own line and changes nothing, and the end check beside it is a <code>FAIL</code>, never a <code>PASS</code>. A daemon runs when <code>sotd.service</code> is active (Linux) or a process of this account runs <code>&lt;prefix&gt;/bin/sotd</code> (Windows: its pipe is listed or a process runs from <code>bin\\sotd.exe</code>); a socket file alone, which a crash leaves behind, is no daemon. On Linux <code>--restart-daemon</code> answers it for the unit and a daemon the run cannot restart is stopped by hand; on Windows a daemon that already runs the target version is asked too before anything stops it.</p></li><li><p><code>target:</code> says the machine runs a build of the line (a <code>+</code> in its version). Install a pack of the line with <code>--archive &lt;folder&gt;</code>, a folder <code>scripts/pack-build.sh</code> packed; that runs the <code>install.sh</code> of the checkout that made the pack, not the installed one. A release named with <code>--version</code> is usually older than a build of the line and moves the machine back, so a person chooses it.</p></li><li><p><code>direction:</code> says the newest release is older than what runs here. Add <code>--version vX.Y.Z</code> to go back on purpose.</p></li></ul><p>A daemon that a window holds, or that the launcher started, is not restarted by the update (the built-in <code>auto</code> mode keeps a daemon under an attached window too). It is asked which REPLs are live and whether the Pluto server is running all the same, and the <code>ONE STEP LEFT</code> line names them and the command that fits the computer (the launcher, <code>systemctl --user restart sotd.service</code>, or starting <code>sotd</code> by hand). Until it is taken the old daemon runs beside the new <code>repo/current</code> and <code>bin/sot-capsule</code>.</p><p>Without a network, <code>--archive &lt;folder&gt;</code> installs from a folder carried to the machine (the base clone still needs the repo&#39;s origin unless it already holds the commit). On Windows the frontend stages the update and <code>launch-sot.ps1</code> applies it at the next launch, below.</p><h2 id="What-updates-a-machine" tabindex="-1">What updates a machine <a class="header-anchor" href="#What-updates-a-machine" aria-label="Permalink to &quot;What updates a machine {#What-updates-a-machine}&quot;">​</a></h2><p>Two mechanisms complement rather than compete (release installs only; <strong>a source build, with a <code>+</code> in its version, never self-updates</strong> and updates by <code>git pull</code> and a rebuild):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mechanism</th><th style="text-align:right;">What it does</th><th style="text-align:right;">What you do</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Built-in update check</strong></td><td style="text-align:right;">The backend checks GitHub for new releases daily, <strong>notifies the frontend</strong>, and prepares the whole new version in the background: binaries, a tag-pinned checkout and instantiated Julia environments, verified against the release&#39;s <code>SHA256SUMS</code>. The staged version is applied at the next launch (or daemon restart) as an offline switch, with the previous version kept for rollback.</td><td style="text-align:right;">Nothing: you will see the notice; relaunch when convenient.</td></tr><tr><td style="text-align:right;"><strong>Running the installer</strong></td><td style="text-align:right;">The <strong>complete</strong> update in one command, above: new binaries <em>and</em> the repo checkout moved to the new tag <em>and</em> Julia envs re-instantiated, with one verdict line. It is also what migrates a pre-0.6 install onto the auto-update layout.</td><td style="text-align:right;"><code>bash ~/.local/share/sot/repo/current/scripts/install.sh</code>, or say &quot;update sot from the repo&quot;.</td></tr></tbody></table><p><code>SOT_UPDATE_MODE</code> controls the built-in check: <code>notify</code> (the default) stages and applies at the next launch, <code>off</code> disables it, and <code>auto</code> additionally restarts the backend to apply, if no frontend is attached when the daily check arms an update (otherwise it applies at the next launch or restart). That restarts REPLs and kernels, so their in-memory state is lost, which is why it is opt-in; agent sessions survive it.</p><p>The daemon of a machine runs the check; a window runs it itself only where the daemon does not own updates (a host the topology declares <code>daemon = false</code>, a <code>frontend</code> entry or a <code>--backend</code> frontend-only install whose install runs no daemon, on any OS). A pre-release install follows pre-releases and a plain release follows plain releases; the check never moves an install backwards or into a dev build, and an armed update records the install it was armed over, so <code>sot-apply</code> drops one that no longer fits (the installer moved on, the version is not above the install, the stage has no record of its prepare, or a host that runs a backend meets a prepare that did not instantiate the Julia environments) without stopping the daemon. A host the hub&#39;s <code>hosts.toml</code> names with neither <code>daemon</code> nor <code>frontend</code> runs no <code>sotd</code> and never arms into an install it shares. <code>sotd update stage &lt;folder&gt; --prefix &lt;prefix&gt;</code>, the operator&#39;s command for a packed build, is the one way to arm the same or an older build.</p><p>On <strong>Linux and macOS</strong> each release&#39;s own <code>sot-apply</code> applies the next update, and brings the agent comm (<code>~/.sot-comm</code>) to the applied commit on every role. On <strong>Windows</strong> <code>launch-sot.ps1</code> applies the staged update at the next launch through <code>scripts\\sot-apply.ps1</code>: the same verification and rollback.</p><h2 id="What-the-installer-does-to-the-checkout" tabindex="-1">What the installer does to the checkout <a class="header-anchor" href="#What-the-installer-does-to-the-checkout" aria-label="Permalink to &quot;What the installer does to the checkout {#What-the-installer-does-to-the-checkout}&quot;">​</a></h2><p>The installer fetches tags into <code>$PREFIX/repo/base</code>, adds a worktree for the release at <code>$PREFIX/repo/versions/&lt;tag&gt;</code>, checks that its <code>HEAD</code> is the tag&#39;s recorded commit (a moved tag or a half checkout fails at update time, not at first use), and points <code>$PREFIX/repo/current</code> at it. It refuses to go on only if that new tag&#39;s own folder has local changes. An update keeps the previous version&#39;s folder for rollback, and the previous binaries as <code>bin/*.prev</code>, and removes older folders, except a folder with local changes: the installer names it, keeps it, and removes it on a later update once it is clean. A repair run (the same version again) prunes nothing and keeps both. Do not edit the checkout; it is the manual and the resource tree, and changes in it are not carried to the next version.</p><h2 id="Pinning-and-going-back" tabindex="-1">Pinning and going back <a class="header-anchor" href="#Pinning-and-going-back" aria-label="Permalink to &quot;Pinning and going back {#Pinning-and-going-back}&quot;">​</a></h2><ul><li><p><strong>Pin a release.</strong> Add <code>--version vX.Y.Z</code> (Windows: <code>-Version</code>) to move to (or stay on) a specific tag; the same flag moves you <em>back</em> to an older tag. A run that names what to install (<code>--version</code>, <code>--archive</code>) pins the install: <code>install.json</code> records <code>&quot;pinned&quot;: true</code> and the daily check and the window&#39;s own check leave it alone, so a downgrade is not undone the next morning. The update status says &quot;pinned at &lt;version&gt;: automatic updates stay off for this install until a run that names no version&quot;, and the <code>PASS</code> or <code>ONE STEP LEFT</code> line ends with it. A run that names no version removes the pin, and an <code>install.json</code> with no pin field (every install made before the field existed) is unpinned and follows its channel. Running the version a machine already runs, by name, is how a machine is pinned in place: when its daemon already answers as that version the run writes the pin, drops any update pointer armed over the install, and restarts nothing (on Windows a named run of the installed version fetches no release asset; the prelude still fetches the tag&#39;s <code>install.ps1</code> unless <code>SOT_INSTALL_TAG</code> is set). A build with a <code>+</code> never updates automatically, so a pin changes nothing there.</p></li><li><p><strong>An <code>install.json</code> that cannot be read.</strong> A record cut short (an interrupted write, a bad hand edit) may hold a pin, so automatic updates stay off for that install, and the update status says so in one sentence: &quot;install.json cannot be read at &lt;path&gt; (&lt;cause&gt;); it may hold a pin, so automatic updates stay off until it is repaired by running <code>install.sh --version &lt;version&gt;</code>&quot; (Windows: <code>install.ps1 -Version &lt;version&gt;</code>). That run rewrites the record whole and pins the install at the version; a later run that names no version removes the pin. A leading byte-order mark alone (a record saved by Notepad) is not unreadable. On Windows a record that is missing while <code>bin\\sotd.exe</code> exists is treated the same way, and the status says &quot;install.json is missing at &lt;path&gt; ...&quot; with the same run to write it again (it works while Ship of Tools runs: the installer never takes an install with a <code>bin\\sotd.exe</code> for a new one). &quot;Update sot from the repo&quot;, which names no version, repairs a record it cannot read too, and does not pin.</p></li><li><p><strong>Automatic rollback.</strong> Applying a staged update is an offline pointer flip done by <code>sot-apply</code>, which records the previous install as <em>last good</em>. The <code>--local</code> launcher runs <code>sot-apply --rollback</code> if the frontend exits with an error within 10 seconds twice in the 30 minutes after an update. Windows rolls back after a single such exit within two hours of the update, through <code>launch-sot.ps1</code>. A <code>--backend</code> (frontend-only) install on Linux or macOS does not roll back on its own: run the installer with <code>--version</code> to go back.</p></li></ul>`,24)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
